CREATE TABLE IF NOT EXISTS factories(id BIGINT AUTO_INCREMENT PRIMARY KEY, factoryName VARCHAR(100) NOT NULL UNIQUE, factoryDescription VARCHAR(1000), contactEmail VARCHAR(200));
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, role VARCHAR(24) NOT NULL, factoryName VARCHAR(100), factoryDescription VARCHAR(1000), contactEmail VARCHAR(200), realName VARCHAR(100), createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(factoryName) REFERENCES factories(factoryName));
CREATE TABLE IF NOT EXISTS devices(id BIGINT AUTO_INCREMENT PRIMARY KEY, deviceName VARCHAR(100) NOT NULL, deviceDescription VARCHAR(1000), factoryName VARCHAR(100) NOT NULL, FOREIGN KEY(factoryName) REFERENCES factories(factoryName));
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY, productName VARCHAR(100) NOT NULL, quantity INT NOT NULL CHECK(quantity>0), status VARCHAR(24) NOT NULL DEFAULT 'PENDING', version INT NOT NULL DEFAULT 0, factoryName VARCHAR(100) NOT NULL, ownerUsername VARCHAR(64) NOT NULL, FOREIGN KEY(factoryName) REFERENCES factories(factoryName), FOREIGN KEY(ownerUsername) REFERENCES users(username));

CREATE TABLE IF NOT EXISTS order_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, orderId BIGINT NOT NULL, fromStatus VARCHAR(24), toStatus VARCHAR(24) NOT NULL, actor VARCHAR(64) NOT NULL, orderVersion INT NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(orderId,orderVersion), FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE CASCADE);

-- Additive local H2 migration: existing rows retain status and ownership.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS priority VARCHAR(16) DEFAULT 'NORMAL' NOT NULL;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS dueDate DATE;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS notes VARCHAR(2000);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS completedQuantity INT DEFAULT 0 NOT NULL;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS rejectedQuantity INT DEFAULT 0 NOT NULL;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS status VARCHAR(24) DEFAULT 'AVAILABLE' NOT NULL;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS category VARCHAR(100) DEFAULT '加工设备' NOT NULL;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS location VARCHAR(100);
ALTER TABLE devices ADD COLUMN IF NOT EXISTS dailyCapacityMinutes INT DEFAULT 480 NOT NULL;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS serviceDueDate DATE;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS maintenanceNote VARCHAR(1000);
ALTER TABLE devices ADD COLUMN IF NOT EXISTS version INT DEFAULT 0 NOT NULL;
ALTER TABLE order_events ADD COLUMN IF NOT EXISTS eventType VARCHAR(32) DEFAULT 'STATUS' NOT NULL;
ALTER TABLE order_events ADD COLUMN IF NOT EXISTS note VARCHAR(2000);
CREATE TABLE IF NOT EXISTS production_plans(orderId BIGINT PRIMARY KEY, deviceId BIGINT NOT NULL, plannedStart TIMESTAMP NOT NULL, plannedEnd TIMESTAMP NOT NULL, notes VARCHAR(1000), FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(deviceId) REFERENCES devices(id));
CREATE TABLE IF NOT EXISTS production_reports(id BIGINT AUTO_INCREMENT PRIMARY KEY, orderId BIGINT NOT NULL, goodQuantity INT NOT NULL CHECK(goodQuantity>=0), rejectedQuantity INT NOT NULL CHECK(rejectedQuantity>=0), notes VARCHAR(1000), actor VARCHAR(64) NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS production_issues(id BIGINT AUTO_INCREMENT PRIMARY KEY, orderId BIGINT NOT NULL, type VARCHAR(24) NOT NULL, severity VARCHAR(16) NOT NULL, description VARCHAR(2000) NOT NULL, status VARCHAR(16) DEFAULT 'OPEN' NOT NULL, resolution VARCHAR(2000), actor VARCHAR(64) NOT NULL, resolvedBy VARCHAR(64), createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, resolvedAt TIMESTAMP, version INT DEFAULT 0 NOT NULL, FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS device_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, deviceId BIGINT NOT NULL, status VARCHAR(24) NOT NULL, note VARCHAR(1000), actor VARCHAR(64) NOT NULL, deviceVersion INT NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, FOREIGN KEY(deviceId) REFERENCES devices(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS plan_device_time ON production_plans(deviceId,plannedStart,plannedEnd);
CREATE INDEX IF NOT EXISTS issues_order_status ON production_issues(orderId,status);

-- Material quantities are integer base units; stock and reservations share one transaction.
CREATE TABLE IF NOT EXISTS materials (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, factoryName VARCHAR(100) NOT NULL,
 sku VARCHAR(64) NOT NULL, name VARCHAR(100) NOT NULL, unit VARCHAR(16) NOT NULL,
 onHand BIGINT NOT NULL DEFAULT 0, reserved BIGINT NOT NULL DEFAULT 0,
 version INT NOT NULL DEFAULT 0, UNIQUE(factoryName,sku),
 CHECK(onHand >= reserved AND reserved >= 0),
 FOREIGN KEY(factoryName) REFERENCES factories(factoryName) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS bom_headers (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, factoryName VARCHAR(100) NOT NULL,
 productName VARCHAR(100) NOT NULL, version INT NOT NULL DEFAULT 0,
 UNIQUE(factoryName,productName), FOREIGN KEY(factoryName) REFERENCES factories(factoryName) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS bom_lines (
 bomId BIGINT NOT NULL, materialId BIGINT NOT NULL, units BIGINT NOT NULL CHECK(units>0),
 PRIMARY KEY(bomId,materialId), FOREIGN KEY(bomId) REFERENCES bom_headers(id) ON DELETE CASCADE,
 FOREIGN KEY(materialId) REFERENCES materials(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS material_reservations (
 orderId BIGINT PRIMARY KEY, bomVersion INT NOT NULL, status VARCHAR(16) NOT NULL,
 FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS reservation_lines (
 orderId BIGINT NOT NULL, materialId BIGINT NOT NULL, quantity BIGINT NOT NULL CHECK(quantity>0),
 PRIMARY KEY(orderId,materialId), FOREIGN KEY(orderId) REFERENCES material_reservations(orderId) ON DELETE CASCADE,
 FOREIGN KEY(materialId) REFERENCES materials(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS material_ledger (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, materialId BIGINT NOT NULL, orderId BIGINT,
 kind VARCHAR(16) NOT NULL, quantity BIGINT NOT NULL, actor VARCHAR(64) NOT NULL,
 requestId VARCHAR(64), createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(materialId,requestId), FOREIGN KEY(materialId) REFERENCES materials(id) ON DELETE CASCADE,
 FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE SET NULL
);
